test('percent codes round half up', () => {
  const c = mk({ codes: { SPRING: { percent: 10 }, HALF: { percent: 50 } } });
  c.add('AP-1', 3);
  c.applyCode('Spring');
  assert.equal(c.code, 'SPRING');
  assert.equal(c.discount(), Math.floor((1350 * 10 * 2 + 100) / 200));
  assert.equal(c.total(), 1350 - c.discount());
  c.applyCode('half');
  assert.equal(c.discount(), 675);
