  assert.equal(c.total(), 620);
  c.add('HN-1', Math.ceil(3000 / 1100));
  assert.equal(c.discount(), 700);
  assert.equal(c.total(), c.subtotal() - 700);
  c.applyCode('free');
  assert.equal(c.discount(), c.subtotal());
  assert.equal(c.total(), 0);
