  assert.equal(c.code, null);
  c.add('HN-1');
  assert.throws(() => c.applyCode('NOPE'), /unknown code/);
  assert.equal(c.code, null);
  c.applyCode('A');
  assert.throws(() => c.applyCode('C'), Error);
  assert.equal(c.code, 'A');
  c.applyCode('B');
  assert.equal(c.total(), 880);
  c.add('HN-1');
  assert.equal(c.total(), 1760);
  assert.equal(mk().discount(), 0);
});

