  const c = mk();
  c.add('AP-1');
  assert.equal(c.tax(), 0);
  assert.equal(c.total(), 450);
  for (const bad of [-1, 12.5, '800']) assert.throws(() => mk({ taxBp: bad }), RangeError);
  const half = mk({ taxBp: 5000 });
  half.add('EG-6');
  half.add('AP-1');
  assert.equal(half.tax(), 405);
  assert.equal(mk({ taxBp: 1000 }).tax(), 0);
