  'CH-2': { name: 'Goat cheese', price: 780 },
  'EG-6': { name: 'Eggs (6)', price: 360 },
  'BR-1': { name: 'Sourdough', price: 620 },
};
const mk = (options) => new Cart(CATALOG, options);

