'use strict';
const { money } = require('./format');

// n / d rounded to the nearest integer, halves up (n >= 0, d > 0)
const roundHalfUp = (n, d) => Math.floor((2 * n + d) / (2 * d));

class Cart {
  constructor(catalog, options = {}) {
    this.catalog = catalog;
    this.items = new Map();
    this.codes = options.codes || {};
    this.code = null;
    this.taxBp = options.taxBp === undefined ? 0 : options.taxBp;
    if (!Number.isInteger(this.taxBp) || this.taxBp < 0) throw new RangeError('taxBp must be a non-negative integer');
    this._plugins = [];
    this._cache = null;
    this._computations = 0;
    this.currency = options.currency === undefined ? 'USD' : options.currency;
    money(0, this.currency);
  }

  unitPrice(sku, qty) {
    const item = this.catalog[sku];
    return item.bulk && qty >= item.bulk.min ? item.bulk.price : item.price;
  }

  add(sku, qty = 1) {
    if (!Number.isInteger(qty) || qty < 1) throw new RangeError('qty must be a positive integer');
    if (!this.catalog[sku]) throw new Error(`unknown sku: ${sku}`);
