  assert.deepEqual(c.lines(), []);
  c.add('AP-1', 2);
  assert.throws(() => c.remove('AP-1', 3), RangeError);
  assert.throws(() => c.remove('AP-1', 0), RangeError);
  assert.throws(() => c.remove('EG-6'), /not in cart/);
  assert.equal(c.lines()[0].qty, 2);
});

