  const cat = { ...CATALOG, 'HN-1': { name: 'Honey jar', price: 1100, bulk: { min: 5, price: 1000 } } };
  const c = new Cart(cat);
  c.add('HN-1', 5 - 1);
  assert.equal(c.lines()[0].unitPrice, 1100);
  assert.equal(c.subtotal(), 1100 * (5 - 1));
  c.add('HN-1');
